import {financialPresentation,presentationHTML} from './record-presentation.js?v=34';
import {activityItems,selectActivities,activityGroups} from './activities-model.js?v=32';
import {validDate,moveDate,presetRange,rangeDays} from './range-model.js?v=17';

const types=[['all','Todas as atividades'],['obligation','Compromissos'],['forecast','Previsões'],['task','Tarefas']];
const tone=g=>({overdue:'red',deviation:'amber',verify:'blue',due:'amber',resolved:'green',planned:'neutral'})[g]||'neutral';
export function createActivities(a){
  const {esc,fullDate,money,btn}=a,states=new Map();
  const selection=()=>{if(!states.has(a.company))states.set(a.company,{preset:'next30',start:a.NOW,end:moveDate(a.NOW,29),type:'all',direction:'all',account:'all',status:'active',search:'',page:1,priorPage:1,collapsed:new Set(),error:''});return states.get(a.company);};
  const dataset=()=>{const s=selection(),items=activityItems(a.state,a.company,a.NOW);return {...selectActivities(items,s),items};};
  const refresh=()=>a.render();
  const attrs=(kind,id)=>`data-open="${esc(kind)}" data-id="${esc(id)}"`;
  const refButtons=refs=>refs.map(r=>btn(esc(r.type)+': '+esc(r.label),attrs(r.kind,r.id),'activity-reference')).join('');
  function row(item){
    const c=item.context,isTask=item.kind==='task',isForecast=item.kind==='forecast',record=c.record;
    const active=item.group!=='resolved'&&!item.hidden;
    const presentation=item.kind==='obligation'?financialPresentation(a.state,'obligation',record,a.NOW):null;
    const task=item.linkedTasks.find(t=>!t.done),hasPriorTask=item.linkedTasks.length>0;
    const docs=c.direct.filter(r=>r.kind==='document');
    const related=c.direct.filter(r=>r.kind!=='document');
    const value=isTask?'':item.type==='forecast'?`<span>Valor a confirmar</span><strong>${money(item.amount??item.expected)}</strong>`:`<span>${item.direction>0?'A receber':'A pagar'} · em aberto</span><strong>${money(item.balance)}</strong><small>Total informado: ${money(item.expected)}</small>`;
    return `<article class="activity-row ${item.type}" data-flow="${item.direction>0?'incoming':item.direction<0?'outgoing':'neutral'}" data-activity-id="${esc(item.id)}"><div class="activity-main"><div class="activity-meta"><span class="activity-kind">${esc(item.origin)}</span><span class="control-status ${tone(item.group)}">${esc(item.label)}</span>${item.direction?`<span>${item.direction>0?'Entrada / recebimento':'Saída / pagamento'}</span>`:''}</div><h3 class="record-title ${presentation?.complete?'is-reconciled':''}"><button ${attrs(isForecast?'forecast':isTask?'task':'obligation',item.target)}>${esc(c.title)}</button></h3>${presentationHTML(a,presentation)}<div class="activity-context">${c.banks.map(b=>btn(esc(b.name),attrs('bank-account',b.id),'activity-reference')).join('')}${refButtons(related)}${record?.party?`<span>${esc(record.party)}</span>`:''}</div>${record?.expectedDate&&record.expectedDate!==item.date?`<p>Execução acompanhada em ${fullDate(record.expectedDate)} · vencimento original preservado.</p>`:''}${isForecast?`<p>${item.months} meses no histórico · ${c.sourceCount} movimentos de origem. Contrato ou obrigação ainda a identificar.</p>`:''}<p class="activity-reason">${esc(item.detail)}</p>${isTask?`<p>Responsável: ${esc(item.owner||'A definir')}</p>`:''}${docs.length?`<details class="activity-related"><summary>Documentos vinculados (${docs.length})</summary><div>${refButtons(docs)}</div></details>`:!isForecast&&!isTask?'<p class="activity-no-doc">Sem documento vinculado ainda.</p>':''}${item.linkedTasks.length?`<details class="activity-related"><summary>Tarefas relacionadas (${item.linkedTasks.length}) · ${item.linkedTasks.filter(t=>!t.done).length} aberta(s)</summary><p>São as mesmas tarefas da agenda, com seus próprios prazos.</p>${item.linkedTasks.map(t=>btn(`${esc(t.title)} · ${fullDate(t.due)} · ${t.done?'Concluída':'A fazer'}`,attrs('task',t.id),'activity-task-link')).join('')}</details>`:''}</div><div class="activity-side">${value?`<div class="activity-value ${item.direction>0?'income':'expense'}">${value}</div>`:''}<div class="activity-actions">${btn(isForecast?'Ver previsão e fontes':'Acompanhamento',attrs(isForecast?'forecast':'control-item',isForecast?item.target:item.id))}${item.date?btn('Calendário',`data-activity-calendar="${esc(item.id)}"`):''}${isTask?btn(active?'Concluir tarefa':'Reabrir tarefa',`data-toggle-task="${esc(item.target)}"`):active?btn(task?'Abrir tarefa':hasPriorTask?'Reabrir tarefa':'Criar tarefa',task?attrs('task',task.id):attrs('control-task',item.id)):''}</div></div></article>`;
  }
  function groupsHTML(rows,part='main'){
    const s=selection(),groups=activityGroups(rows),pageKey=part==='prior'?'priorPage':'page',pages=Math.max(1,Math.ceil(groups.length/10));s[pageKey]=Math.min(s[pageKey],pages);
    const selected=groups.slice((s[pageKey]-1)*10,s[pageKey]*10);
    return selected.map(g=>{const key=part+':'+(g.date||'undated');return `<details class="activity-day" data-activity-day="${key}" ${s.collapsed.has(key)?'':'open'}><summary><span>${g.date?fullDate(g.date):'Prazo a definir'}</span><small>${g.items.length} atividade(s)</small></summary><div>${g.items.map(row).join('')}</div></details>`;}).join('')+(pages>1?`<nav class="activity-pagination" aria-label="Páginas ${part==='prior'?'das pendências anteriores':'das atividades'}">${btn('Anterior',`data-activity-page="${s[pageKey]-1}" data-activity-part="${part}" ${s[pageKey]===1?'disabled':''}`)}<span>Página ${s[pageKey]} de ${pages} · dias completos</span>${btn('Próxima',`data-activity-page="${s[pageKey]+1}" data-activity-part="${part}" ${s[pageKey]===pages?'disabled':''}`)}</nav>`:'');
  }
  function render(){
    const s=selection(),data=dataset(),values=s.draft||s,summary=data.summary;
    const option=(v,label,current)=>`<option value="${v}" ${v===current?'selected':''}>${label}</option>`;
    return a.titleBlock('Obrigações e atividades','Compromissos, previsões e próximas ações da empresa.',btn('Nova tarefa','data-activity-new="task"','','plus')+btn('Nova obrigação','data-activity-new="obligation"','primary','plus'),'Planejamento e acompanhamento')+
      `<section class="activity-controls" aria-label="Filtrar obrigações e atividades"><div class="activity-period"><label>Período<select data-activity-preset>${[['next30','Próximos 30 dias'],['next90','Próximos 90 dias'],['today','Hoje'],['month','Mês atual'],['year','Ano atual'],['all','Todo o acompanhamento'],['custom','Personalizado']].map(([v,l])=>option(v,l,s.preset)).join('')}</select></label><label>De<input type="date" data-activity-start value="${values.start||''}" min="1900-01-01" max="9999-12-31"></label><label>Até<input type="date" data-activity-end value="${values.end||''}" min="1900-01-01" max="9999-12-31"></label>${btn('Aplicar','data-activity-apply="1"','primary')}</div><div class="activity-range-nav">${btn('Período anterior',`data-activity-shift="-1" ${!s.start?'disabled':''}`)}<b>${s.start?fullDate(s.start)+' — '+fullDate(s.end):'Todas as datas disponíveis'}</b>${btn('Próximo período',`data-activity-shift="1" ${!s.start?'disabled':''}`)}${btn('Ver período no fluxo','data-activity-flow="1"')}</div><p class="activity-error" role="alert">${esc(s.error)}</p><div class="activity-filters"><label>Situação<select data-activity-filter="status">${[['active','Em acompanhamento'],['attention','Precisam de atenção'],['overdue','Atrasadas / vencidas'],['resolved','Concluídas / reconhecidas'],['all','Todas, inclusive encerradas']].map(([v,l])=>option(v,l,s.status)).join('')}</select></label><label>Direção<select data-activity-filter="direction">${[['all','Entradas, saídas e tarefas'],['in','Entradas / a receber'],['out','Saídas / a pagar']].map(([v,l])=>option(v,l,s.direction)).join('')}</select></label><label>Conta<select data-activity-filter="account">${option('all','Todas as contas',s.account)}${a.scope('accounts').map(b=>option(esc(b.id),esc(b.name),s.account)).join('')}</select></label><label>Buscar contexto<input type="search" data-activity-filter="search" value="${esc(s.search)}" placeholder="Descrição, pessoa, ativo…"></label></div><p>O período usa o vencimento, a data prevista ou o prazo da tarefa. Não exige extrato. Direção e conta filtram tarefas apenas quando há vínculo conhecido.</p></section>`+
      `<div class="activity-totals"><div><span>Compromissos a receber</span><strong>${money(summary.incoming)}</strong><small>Saldo em aberto no período</small></div><div><span>Compromissos a pagar</span><strong>${money(summary.outgoing)}</strong><small>Saldo em aberto no período</small></div><div class="forecast"><span>Previsões a confirmar</span><strong>${summary.forecasts}</strong><small>Separadas dos compromissos</small></div><div><span>Tarefas no período</span><strong>${summary.tasks}</strong><small>Ações com prazo próprio</small></div></div>`+
      `<nav class="activity-tabs" aria-label="Tipo de atividade">${types.map(([v,label])=>`<button data-activity-type="${v}" aria-pressed="${v===s.type}" class="${v===s.type?'active':''}">${label} <span>${data.counts[v]}</span></button>`).join('')}</nav>`+
      (data.prior.length?`<details class="activity-prior"><summary>${data.prior.length} pendência(s) anteriores ao período</summary><p>Seguem em acompanhamento e não entram nos totais acima. Uma previsão sem ocorrência identificada ainda precisa de revisão; não é dívida confirmada.</p>${groupsHTML(data.prior,'prior')}</details>`:'')+
      (data.undated.length?`<details class="activity-prior"><summary>${data.undated.length} atividade(s) sem prazo definido</summary>${data.undated.map(row).join('')}</details>`:'')+
      `<section class="activity-list" aria-label="Atividades por dia"><div class="activity-list-head"><h2>${data.rows.length} atividade(s) no período</h2>${btn('Expandir dias','data-activity-expand="1"')}${btn('Recolher dias','data-activity-collapse="1"')}</div>${data.rows.length?groupsHTML(data.rows):`<div class="activity-empty"><h3>Nenhuma atividade com estes filtros</h3><p>Você pode consultar outro intervalo, rever os filtros ou cadastrar um compromisso ou tarefa.</p>${btn('Ver próximos 30 dias · todos os tipos','data-activity-reset="1"')}</div>`}</section><details class="activity-explainer"><summary>Como estas informações se conectam</summary><p>São os mesmos registros do calendário, das tarefas e do painel de controle. Revisões e conclusões aparecem nessas telas sem criar cópias.</p><p>Compromissos cadastrados, previsões e tarefas permanecem distintos. Confirmar uma expectativa não cria obrigação nem pagamento. Concluir uma tarefa não liquida valores. Os saldos em aberto consideram apenas vínculos financeiros confirmados e compatíveis.</p><p>As sugestões do histórico cobrem o mês atual e os próximos dois, além das decisões preservadas. Fora desse horizonte, aparecem os compromissos e tarefas já cadastrados. Falta de extrato exige conferência, sem presumir inadimplência.</p><p>Revisões e vínculos ficam neste navegador, como nas demais telas da prévia.</p></details>`;
  }
  function setRange(start,end,preset='custom'){
    const s=selection();if(!validDate(start)||!validDate(end)||start>end){s.error='Informe duas datas válidas, com o fim igual ou posterior ao início.';refresh();return false;}
    Object.assign(s,{start,end,preset,draft:null,error:'',page:1,priorPage:1});refresh();return true;
  }
  function click(d){
    const s=selection();
    if(d.activityReset){states.delete(a.company);refresh();return true;}
    if(d.activityApply){setRange((s.draft||s).start,(s.draft||s).end);return true;}
    if(d.activityShift&&s.start){const delta=Number(d.activityShift)*rangeDays(s);setRange(moveDate(s.start,delta),moveDate(s.end,delta));return true;}
    if(d.activityType&&types.some(([k])=>k===d.activityType)){s.type=d.activityType;s.page=s.priorPage=1;refresh();return true;}
    if(d.activityPage){s[d.activityPart==='prior'?'priorPage':'page']=Math.max(1,Number(d.activityPage)||1);refresh();return true;}
    if(d.activityExpand||d.activityCollapse){const data=dataset();for(const [part,rows] of [['main',data.rows],['prior',data.prior]])for(const g of activityGroups(rows)){const key=part+':'+(g.date||'undated');if(d.activityExpand)s.collapsed.delete(key);else s.collapsed.add(key);}refresh();return true;}
    if(d.activityNew){const date=s.start||a.NOW;a.setMonth(date.slice(0,7));a.open(d.activityNew==='task'?'newtask':'newobligation','date:'+date);return true;}
    if(d.activityCalendar){const i=dataset().items.find(i=>i.id===d.activityCalendar);if(i?.date){a.selectDate(i.date);a.navigate('home/calendar');}return true;}
    if(d.activityFlow){const rows=dataset().rows,dates=rows.map(i=>i.date).filter(Boolean).sort();a.openCashbook({start:s.start||dates[0]||a.NOW,end:s.end||dates.at(-1)||a.NOW},s.account);return true;}
    return false;
  }
  function change(e){
    const el=e.target,s=selection();
    if(el.hasAttribute('data-activity-start')||el.hasAttribute('data-activity-end')){s.draft??={start:s.start,end:s.end};s.draft[el.hasAttribute('data-activity-start')?'start':'end']=el.value;return true;}
    if(el.hasAttribute('data-activity-filter')){const key=el.dataset.activityFilter;if(['status','direction','account','search'].includes(key)){s[key]=el.value;s.page=s.priorPage=1;refresh();}return true;}
    if(el.hasAttribute('data-activity-preset')){
      const key=el.value;if(key==='all'){Object.assign(s,{start:null,end:null,preset:key,draft:null,error:'',page:1,priorPage:1});refresh();return true;}
      if(key==='custom'){s.preset=key;s.draft={start:s.start||a.NOW,end:s.end||a.NOW};refresh();return true;}
      const r=key==='today'?{start:a.NOW,end:a.NOW}:key==='next30'||key==='next90'?{start:a.NOW,end:moveDate(a.NOW,key==='next30'?29:89)}:presetRange(key,a.NOW);
      setRange(r.start,r.end,key);return true;
    }
    return false;
  }
  document.addEventListener('toggle',e=>{const key=e.target.dataset?.activityDay;if(key&&e.target.isConnected!==false){const s=selection();e.target.open?s.collapsed.delete(key):s.collapsed.add(key);}},true);
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches?.('[data-activity-start],[data-activity-end]')){e.preventDefault();change({target:e.target});click({activityApply:'1'});}});
  return {render,click,change,reveal(date){if(validDate(date)){const s=selection();if(!s.start||date<s.start||date>s.end)Object.assign(s,{start:date,end:date,preset:'custom'});Object.assign(s,{type:'all',direction:'all',account:'all',status:'active',search:'',page:1,priorPage:1,draft:null,error:''});}}};
}
